// Generated by Suite Builder from a crawl of the site. The Jira loop: ready stories in, outcomes back out.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Your Jira names go in jira-loop/jira.properties (jira login fills them in).
// The Jira loop (G-208), run by the suite's pipeline, or by hand:
//   node jira-loop/sync.mjs check    signs in, says what is ready and which statuses it can reach; changes nothing
//   node jira-loop/sync.mjs pull     the stories in the ready statuses, into stories/new/ (answers into stories/done/)
//   node jira-loop/sync.mjs report   each story's outcome as a comment, and its card moved on or back to triage
// A person types the suite's jira command instead (jira login, pull, push: jira-loop/jira.mjs, G-214), which
// runs these, and these for its questions, one line of JSON each: projects, statuses <KEY>, pending.
// Settings: jira-loop/jira.properties (the menu fills them in). The account: the environment first, as a
// pipeline's secrets set it (JIRA_API_TOKEN, and on Jira Cloud JIRA_EMAIL, the account the token belongs
// to), else secrets/jira.login on a person's computer (Username: the email, Password: the token), which
// jira login writes, git never takes, and every pack carries blank.
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SETTINGS = join(ROOT, 'jira-loop', 'jira.properties');
const REPORTED = join(ROOT, 'jira-loop', 'reported.json');
const NEW = join(ROOT, 'stories', 'new');
const DONE = join(ROOT, 'stories', 'done');
const ACCOUNT = join(ROOT, 'secrets', 'jira.login');
/** The first line of every comment this script writes: how it tells its own comments from a person's. */
const MARK = "Suite Builder: the suite's AI crew";

class Stop extends Error {}
class Idle extends Stop {}

/**
 * The team's settings, checked: every name the command needs, and its edition. The menu, connecting,
 * names the site and edition before they are written (JIRA_SITE, JIRA_EDITION).
 */
function settings(needs) {
  if (!existsSync(SETTINGS)) throw new Stop('jira-loop/jira.properties is missing: a rebuild of the suite writes it again.');
  const s = { edition: 'cloud', max: '5' };
  for (const line of readFileSync(SETTINGS, 'utf8').split(/\r?\n/)) {
    const m = /^\s*([a-z]+)\s*=\s*(.*?)\s*$/.exec(line);
    if (m && !line.trimStart().startsWith('#')) s[m[1]] = m[2];
  }
  if (process.env.JIRA_SITE) Object.assign(s, { site: process.env.JIRA_SITE, edition: process.env.JIRA_EDITION || s.edition });
  // Not set up at all: pull and report have nothing to do, and say so; check says what to fill in.
  if (!s.site && !s.project && (process.argv[2] === 'pull' || process.argv[2] === 'report')) throw new Idle('Jira is not set up (jira-loop/jira.properties): nothing to do.');
  const missing = needs.filter((k) => !s[k]);
  if (missing.length) throw new Stop(`Jira is not set up yet: type jira login in the suite's folder, or fill in ${missing.join(', ')} in jira-loop/jira.properties.`);
  if (s.edition !== 'cloud' && s.edition !== 'data-center') throw new Stop(`edition in jira-loop/jira.properties is "${s.edition}": write cloud or data-center.`);
  s.max = Math.max(1, Number.parseInt(s.max, 10) || 5);
  s.site = s.site.replace(/\/+$/, '');
  return s;
}

/** The Jira account: the environment's (a pipeline's secrets), else secrets/jira.login's (a person's computer). */
function account() {
  if (process.env.JIRA_API_TOKEN) return { token: process.env.JIRA_API_TOKEN, email: process.env.JIRA_EMAIL };
  const lines = existsSync(ACCOUNT) ? readFileSync(ACCOUNT, 'utf8').split(/\r?\n/) : [];
  const value = (name) => lines.find((l) => l.startsWith(`${name}:`))?.slice(name.length + 1).trim() || undefined;
  return { token: value('Password'), email: value('Username') };
}

/** The sign-in Jira asks for: an email and an API token on Cloud, a personal access token on Data Center. */
function signIn(s) {
  const { token, email } = account();
  if (!token) throw new Stop('Jira is not connected: type jira login in the suite\'s folder, or, in a pipeline, set JIRA_API_TOKEN in its secrets (never in a file git keeps).');
  if (s.edition === 'data-center') return `Bearer ${token}`;
  if (!email) throw new Stop('No email for the Jira token: on Jira Cloud the token goes with the email of the account it belongs to (JIRA_EMAIL, or Username: in secrets/jira.login).');
  return `Basic ${Buffer.from(`${email}:${token}`).toString('base64')}`;
}

const WHY = {
  401: 'Jira refused the sign-in: the token (and the email on Cloud) is wrong or expired: jira login again, or check JIRA_API_TOKEN in the pipeline.',
  403: 'the account signed in may not do this: give it permission to browse, comment on and move the project\'s issues.',
  404: 'Jira has no such thing: check site and project in jira-loop/jira.properties.',
};

/** One call to Jira's version 2 REST API, which both editions answer alike. */
async function call(s, auth, method, path, body) {
  let res;
  try {
    res = await fetch(`${s.site}${path}`, {
      method,
      headers: { Authorization: auth, Accept: 'application/json', ...(body ? { 'Content-Type': 'application/json' } : {}) },
      body: body ? JSON.stringify(body) : undefined,
    });
  } catch (e) {
    throw new Stop(`Jira at ${s.site} did not answer (${e.cause?.code ?? e.message}): check site in jira-loop/jira.properties, and that the pipeline can reach it.`);
  }
  if (!res.ok) throw new Stop(`Jira answered ${res.status} to ${method} ${path.split('?')[0]}: ${WHY[res.status] ?? (await res.text()).slice(0, 200)}`);
  return res.status === 204 ? null : res.json();
}

/** The statuses that mark a story ready (the watch flags): one, or several separated by commas. */
const watched = (s) => s.ready.split(',').map((r) => r.trim()).filter(Boolean);
const saidWatched = (s) => watched(s).map((r) => `"${r}"`).join(' or ');

/**
 * The stories waiting in a ready status, oldest first, but those in `skip`. Cloud searches at /search/jql,
 * Data Center at /search. A status name may hold brackets or quotes (QA Go (BA approved)): each is quoted.
 */
async function ready(s, auth, max, skip = []) {
  const quoted = (v) => `"${v.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
  const except = skip.length ? ` AND key not in (${skip.join(', ')})` : '';
  const jql = `project = "${s.project}" AND status in (${watched(s).map(quoted).join(', ')})${except} ORDER BY created ASC`;
  const where = s.edition === 'cloud' ? '/rest/api/2/search/jql' : '/rest/api/2/search';
  const found = await call(s, auth, 'GET', `${where}?jql=${encodeURIComponent(jql)}&fields=summary,description,status&maxResults=${max}`);
  return found.issues ?? [];
}

async function comments(s, auth, key) {
  return (await call(s, auth, 'GET', `/rest/api/2/issue/${key}/comment?maxResults=1000`)).comments ?? [];
}

const ownComment = (c) => (c.body ?? '').startsWith(MARK);
// The crew's note goes in {noformat}, so Jira shows its ---- lines as written, not as its own markup.
const withoutMark = (body) => body.slice(MARK.length).replace(/\{noformat\}/g, '').trim();
/** A person's comment as the story's answer: its first line after "Answer:", the rest indented under it. */
const answer = (body) => `Answer: ${body.trim().split(/\r?\n/).join('\n  ')}`;

/** The story's id, as stories/AI-INSTRUCTIONS.md reads it from a file name: its first word shaped like ENG-12. */
function idOf(file) {
  return /^([A-Za-z][A-Za-z0-9]*-\d+)\b/.exec(file)?.[1]?.toUpperCase() ?? null;
}

/** The story files with a Jira key of the project, by key: where each is, and its text. */
function storyFiles(s) {
  const out = new Map();
  for (const [dir, where] of [[NEW, 'new'], [DONE, 'done']]) {
    if (!existsSync(dir)) continue;
    for (const file of readdirSync(dir).sort()) {
      const id = idOf(file);
      if (id?.startsWith(`${s.project.toUpperCase()}-`)) out.set(id, { where, path: join(dir, file), file, text: readFileSync(join(dir, file), 'utf8') });
    }
  }
  return out;
}

/** The file name for a story: its key, then its summary's words (the story's title of record). */
function fileName(key, summary) {
  const words = (summary ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 60).trim();
  return `${key}${words ? ` ${words}` : ''}.txt`;
}

/**
 * What the crew decided for a story, from its file: the last IMPLEMENTED note of a file in stories/done/
 * (moved on when it says "Not implemented: none", back to triage when a criterion waits on the BA), or the
 * last PUSHBACK of a file in stories/new/ with no answer under it yet. Nothing decided: null.
 */
function outcome(story) {
  if (story.where === 'done') {
    const at = story.text.lastIndexOf('---- IMPLEMENTED');
    if (at < 0) return null;
    const block = story.text.slice(at).trimEnd();
    const waiting = block.split(/\r?\n/).filter((l) => /^Not implemented:/.test(l) && !/^Not implemented:\s*none\b/i.test(l));
    return { block, done: waiting.length === 0 };
  }
  const at = story.text.lastIndexOf('---- PUSHBACK');
  if (at < 0) return null;
  const block = story.text.slice(at).trimEnd();
  if (/^Answer:/m.test(block)) return null;
  return { block, done: false };
}

function hash(text) {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 0x01000193) >>> 0;
  return h.toString(16).padStart(8, '0');
}

function reported() {
  return existsSync(REPORTED) ? JSON.parse(readFileSync(REPORTED, 'utf8')) : {};
}

/** The move Jira offers a card to a status, by the status's name (or the move's): null when it offers none. */
async function moveTo(s, auth, key, status) {
  const to = (await call(s, auth, 'GET', `/rest/api/2/issue/${key}/transitions`)).transitions ?? [];
  const move = to.find((t) => [t.to?.name, t.name].some((n) => n?.toLowerCase() === status.toLowerCase()));
  return { move, offers: to.map((t) => t.to?.name ?? t.name).join(', ') || 'nothing' };
}

/**
 * A story taken (G-215): its card moved to the claimed status, so no one else takes it and the board shows
 * it is being worked on. Taken by someone else since the search (no longer in a ready status), or no move
 * to the claimed status: not taken, and why said. No claimed status set: the card stays where it is.
 */
async function claim(s, auth, key) {
  if (!s.claimed) return true;
  const now = (await call(s, auth, 'GET', `/rest/api/2/issue/${key}?fields=status`)).fields?.status?.name ?? '';
  if (!watched(s).some((r) => r.toLowerCase() === now.toLowerCase())) {
    console.log(`${key}: not pulled: it moved to "${now}" since (someone else took it).`);
    return false;
  }
  const { move, offers } = await moveTo(s, auth, key, s.claimed);
  if (!move) {
    console.log(`${key}: not pulled: Jira offers no move to "${s.claimed}" from "${now}" (it offers: ${offers}). Add that move to the Jira workflow, or choose another claimed status (jira claim).`);
    process.exitCode = 1;
    return false;
  }
  await call(s, auth, 'POST', `/rest/api/2/issue/${key}/transitions`, { transition: { id: move.id } });
  return true;
}

/** check: signs in, and says what is ready and whether the two statuses a report moves cards to can be reached. Changes nothing. */
async function check(s, auth) {
  const me = await call(s, auth, 'GET', '/rest/api/2/myself');
  console.log(`Signed in to ${s.site} as ${me.displayName ?? me.name ?? me.emailAddress}.`);
  const issues = await ready(s, auth, s.max);
  console.log(`${issues.length === 0 ? 'No' : issues.length} ${issues.length === 1 ? 'story' : 'stories'} in ${saidWatched(s)} in ${s.project}${issues.length >= s.max ? ` (the first ${s.max}: max in jira-loop/jira.properties)` : ''}.`);
  for (const i of issues) console.log(`  ${i.key}  ${i.fields?.summary ?? ''}`);
  if (issues.length === 0) return;
  const to = (await call(s, auth, 'GET', `/rest/api/2/issue/${issues[0].key}/transitions`)).transitions ?? [];
  const from = issues[0].fields?.status?.name ?? watched(s)[0];
  // With a claimed status, a pull moves the card there, and a push moves it on from there: only the claim
  // can be checked from a ready card; the rest, from where it would be.
  for (const status of s.claimed ? [s.claimed] : [s.implemented, s.triage]) {
    const ok = to.some((t) => [t.to?.name, t.name].some((n) => n?.toLowerCase() === status.toLowerCase()));
    console.log(`  "${status}": ${ok ? `reachable from "${from}"` : `not reachable from "${from}" (Jira offers: ${to.map((t) => t.to?.name ?? t.name).join(', ') || 'nothing'})`}`);
  }
  if (s.claimed) console.log(`  "${s.implemented}" and "${s.triage}": a push moves a card there from "${s.claimed}"; the push says if Jira refuses.`);
}

/**
 * pull: each ready story into stories/new/, written from Jira (its summary, description, the comments
 * before the crew's first, then each of the crew's comments with the people's answers under it), so a
 * story pushed back and answered comes back whole. A story already in stories/done/ gets only the
 * answers it lacks. A file whose outcome is not yet reported is left alone: report first.
 */
async function pull(s, auth) {
  const stories = storyFiles(s);
  const done = reported();
  // A story already in stories/new/ that the crew has not decided yet is left as it is, and out of the
  // search: pulled again it would be written over, and take the place of the next story waiting in Jira.
  const waiting = [...stories].filter(([, story]) => story.where === 'new' && !outcome(story)).map(([key]) => key);
  if (waiting.length) console.log(`Already here, waiting for the crew: ${waiting.join(', ')} (not pulled again).`);
  const found = await ready(s, auth, s.max + 1, waiting);
  const issues = found.slice(0, s.max);
  if (issues.length === 0) console.log(`No ${waiting.length ? 'other ' : ''}stories in ${saidWatched(s)}.`);
  for (const issue of issues) await pullOne(s, auth, issue, stories, done);
  if (found.length > s.max) console.log(`More stories wait in ${saidWatched(s)} (max is ${s.max} a pull, in jira-loop/jira.properties): jira pull again takes the next ones.`);
}

/** One ready story into stories/new/ (or its answers into stories/done/), claimed first: true when taken. */
async function pullOne(s, auth, issue, stories, done) {
  {
    const key = issue.key.toUpperCase();
    const all = await comments(s, auth, issue.key);
    const first = all.findIndex(ownComment);
    const had = stories.get(key);
    const decided = had && outcome(had);
    if (decided && done[key] !== hash(decided.block)) {
      console.log(`${key}: left as it is: its outcome is not reported yet (node jira-loop/sync.mjs report).`);
      return false;
    }
    if (had?.where === 'done') {
      const answers = all.slice(Math.max(first, 0)).filter((c, i, list) => !ownComment(c) && list.slice(0, i).some(ownComment)).map((c) => answer(c.body)).filter((a) => !had.text.includes(a));
      if (answers.length === 0) {
        console.log(`${key}: in stories/done/, no new answer in Jira.`);
        return false;
      }
      if (!(await claim(s, auth, key))) return false;
      writeFileSync(had.path, `${had.text.trimEnd()}\n${answers.join('\n')}\n`);
      console.log(`${key}: ${answers.length} answer${answers.length === 1 ? '' : 's'} added to stories/done/${had.file}.`);
      return true;
    }
    const before = (first < 0 ? all : all.slice(0, first)).filter((c) => !ownComment(c));
    const parts = [`${key} ${issue.fields?.summary ?? ''}`.trim(), '', (issue.fields?.description ?? '').trim() || '(no description in Jira)'];
    if (before.length) parts.push('', 'Comments in Jira:', ...before.map((c) => `- ${c.author?.displayName ?? 'someone'}: ${c.body.trim().split(/\r?\n/).join('\n  ')}`));
    for (const c of first < 0 ? [] : all.slice(first)) parts.push(...(ownComment(c) ? ['', withoutMark(c.body)] : [answer(c.body)]));
    if (!(await claim(s, auth, key))) return false;
    mkdirSync(NEW, { recursive: true });
    if (had) rmSync(had.path);
    const name = fileName(key, issue.fields?.summary);
    writeFileSync(join(NEW, name), `${parts.join('\n')}\n`);
    console.log(`${key}: ${had ? 'written again' : 'pulled'} to stories/new/${name}${s.claimed ? `, and moved to "${s.claimed}"` : ''}.`);
    return true;
  }
}

// ---- For the coordinator (jira-loop/agents.mjs, G-216): one story per agent ----

/** queue: every story in a ready status, oldest first, as JSON: key, and its text (to tell which pages it touches). */
async function queue(s, auth) {
  const all = await ready(s, auth, 1000);
  console.log(JSON.stringify(all.map((i) => ({ key: i.key.toUpperCase(), text: `${i.fields?.summary ?? ''}\n${i.fields?.description ?? ''}` }))));
}

/** take <KEY>: that one story claimed and pulled; exit 3 when it is no longer there to take. */
async function take(s, auth) {
  const key = (process.argv[3] ?? '').toUpperCase();
  const issue = (await ready(s, auth, 1000)).find((i) => i.key.toUpperCase() === key);
  if (!issue || !(await pullOne(s, auth, issue, storyFiles(s), reported()))) process.exitCode = 3;
}

/** note <KEY> <text>: a comment of the crew's on the card (a pull request proposed, say). */
async function note(s, auth) {
  await call(s, auth, 'POST', `/rest/api/2/issue/${process.argv[3]}/comment`, { body: `${MARK}\n${process.argv[4] ?? ''}` });
}

/** unclaim <KEY> <why>: the card back in the first ready status, with why, for another agent to take. */
async function unclaim(s, auth) {
  const key = process.argv[3];
  const { move } = await moveTo(s, auth, key, watched(s)[0]);
  await call(s, auth, 'POST', `/rest/api/2/issue/${key}/comment`, { body: `${MARK}\nBack in the queue: ${process.argv[4] ?? ''}` });
  if (move) await call(s, auth, 'POST', `/rest/api/2/issue/${key}/transitions`, { transition: { id: move.id } });
}

/** report: each story the crew decided, once: its note as a comment, then its card moved on (all of it done) or back to triage. */
async function report(s, auth) {
  const done = reported();
  let any = false;
  // report <KEY>: that story only (the coordinator's agents, each on its own story).
  const only = process.argv[3]?.toUpperCase();
  for (const [key, story] of storyFiles(s)) {
    if (only && key !== only) continue;
    const decided = outcome(story);
    if (!decided || done[key] === hash(decided.block)) continue;
    any = true;
    const status = decided.done ? s.implemented : s.triage;
    // Already on the card (another machine reported it, or reported.json was not kept): recorded, not posted again.
    const body = `${MARK}\n{noformat}\n${decided.block}\n{noformat}`;
    if ((await comments(s, auth, key)).some((c) => c.body === body)) {
      done[key] = hash(decided.block);
      writeFileSync(REPORTED, `${JSON.stringify(done, null, 2)}\n`);
      console.log(`${key}: already reported in Jira.`);
      continue;
    }
    const { move, offers } = await moveTo(s, auth, key, status);
    if (!move) {
      console.log(`${key}: not reported: Jira offers no move to "${status}" from where the card is (it offers: ${offers}). Fix the status name in jira-loop/jira.properties or the Jira workflow; the next report tries again.`);
      process.exitCode = 1;
      continue;
    }
    await call(s, auth, 'POST', `/rest/api/2/issue/${key}/comment`, { body });
    await call(s, auth, 'POST', `/rest/api/2/issue/${key}/transitions`, { transition: { id: move.id } });
    done[key] = hash(decided.block);
    writeFileSync(REPORTED, `${JSON.stringify(done, null, 2)}\n`);
    console.log(`${key}: ${decided.done ? 'implemented' : 'sent back'}; commented, and moved to "${status}".`);
  }
  if (!any) console.log('Nothing new to report.');
}

/** projects (for the menu): who signed in, and the projects the account can see. */
async function projects(s, auth) {
  const me = await call(s, auth, 'GET', '/rest/api/2/myself');
  const all = await call(s, auth, 'GET', '/rest/api/2/project');
  console.log(JSON.stringify({ me: me.displayName ?? me.name ?? me.emailAddress, projects: (all ?? []).map((p) => ({ key: p.key, name: p.name })) }));
}

/** statuses <KEY> (for the menu): every status the project's workflows have, each once, in Jira's order. */
async function statuses(s, auth) {
  const types = await call(s, auth, 'GET', `/rest/api/2/project/${encodeURIComponent(process.argv[3] ?? s.project)}/statuses`);
  console.log(JSON.stringify([...new Set((types ?? []).flatMap((t) => (t.statuses ?? []).map((x) => x.name)))]));
}

/** pending (for the menu; no sign-in): what report would send, story by story. */
async function pending(s) {
  const done = reported();
  const out = [];
  for (const [key, story] of storyFiles(s)) {
    const decided = outcome(story);
    if (decided && done[key] !== hash(decided.block)) out.push({ key, file: story.file, to: decided.done ? s.implemented : s.triage, done: decided.done, note: decided.block });
  }
  console.log(JSON.stringify(out));
}

const FULL = ['site', 'project', 'ready', 'implemented', 'triage'];
/** Each command, with the settings it needs, and whether it signs in. */
const COMMANDS = {
  check: [check, FULL, true], pull: [pull, FULL, true], report: [report, FULL, true],
  queue: [queue, FULL, true], take: [take, FULL, true], note: [note, FULL, true], unclaim: [unclaim, FULL, true],
  projects: [projects, ['site'], true], statuses: [statuses, ['site'], true], pending: [pending, ['project', 'implemented', 'triage'], false],
};
const [command, needs, signs] = COMMANDS[process.argv[2]] ?? [];
if (!command) {
  console.log('node jira-loop/sync.mjs check | pull | report   (what each does: the top of this file)');
  process.exitCode = process.argv[2] ? 1 : 0;
} else {
  try {
    const s = settings(needs);
    await command(s, signs ? signIn(s) : null);
  } catch (e) {
    if (!(e instanceof Stop)) throw e;
    console.error(e.message);
    process.exitCode = e instanceof Idle ? 0 : 1;
  }
}
